// === Tab: mySketch ===
let isDrawing = false;
let numTrees = 0;

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(200);
  frameRate(30);
  smooth();
  drawBG();
}

function draw() {
  translate(0, 250);
  if (!isDrawing && numTrees <= 70) {
    numTrees++;
    let sze = random(50, 250);
    branch(random(-50, width + 50), height + 5, -PI / 2, sze, sze / 10, 0);
  } else {
	  noLoop()
  }
}

function branch(startX, startY, ang, len, wt, col) {
  isDrawing = true;
  let numSegs = 0;
  if (len > 50) numSegs = 10;
  else if (len > 30 && len <= 50) numSegs = 5;
  else if (len <= 30) numSegs = 1;
  let segLen = len / numSegs;
  let nextSegWt = wt * 0.6;

  col += 10;

  // divide each branch into articulated (zig-zag) segments
  for (let i = 0; i < numSegs; i++) {
    let varyAng = random(-PI / 2, PI / 2) * 0.05;
    let varySegLen = random(0.5, 1.5);
    let endX = startX + cos(ang + varyAng) * (segLen * varySegLen);
    let endY = startY + sin(ang + varyAng) * (segLen * varySegLen);
    let segWeight = map(i, 0, numSegs, wt, nextSegWt); // slightly smaller as segs are added

    drawBranchSeg(startX, startY, endX, endY, segWeight, col);

    startX = endX;
    startY = endY;
  }

  if (len > 10) {
    len *= 0.66;

    if (len > 30) {
      branch(startX, startY, ang + random(-PI / 6, 0), len, nextSegWt, col);
      branch(startX, startY, ang + random(0, PI / 6), len, nextSegWt, col);
    } else if (len <= 30) {
      let numBranches = floor(random(2, 4));
      for (let i = 0; i < numBranches; i++) {
        let newAng = ang + random(-PI / 4, PI / 4);
        branch(startX, startY, newAng, len, nextSegWt, col);
      }
    }
  }
  isDrawing = false;
}

function drawBranchSeg(startX, startY, endX, endY, wt, col) {
  let len = sqrt(sq(endX - startX) + sq(endY - startY));

  if (wt < 3) {
    strokeWeight(wt);
    stroke(col + ((180 - col) / 2), 200);
    line(startX, startY, endX, endY);
  } else if (wt >= 3) {
    push();
    translate(startX, startY);
    rotate(-PI / 2 + atan2(endY - startY, endX - startX));

    let incr = (220 - col) / wt;
    for (let i = 0; i <= wt; i++) {
      let x1 = -wt / 2 + i;
      let y1 = 0;
      let x2 = -wt / 2 + i;
      let y2 = len;
      stroke(col + i * incr);
      strokeWeight(1);
      line(x1, y1, x2, y2);
    }

    // bark imperfections
    noStroke();
    fill(0);
    for (let j = 0; j < wt * 2; j++) {
      let x = random(-((wt / 2) - (wt / 20)), (wt / 2) - (wt / 20));
      let y = random(len);
      if (random(1) < 0.2) {
        ellipse(x, y, wt * random(0.1, 0.15), wt * random(0.1, 0.15));
      } else {
        ellipse(x, y, wt * random(0.005, 0.1), wt * random(0.005, 0.1));
      }
    }
    pop();
  }
}

function drawBG() {
  let c1 = color(200);
  let c2 = color(245);
  noStroke();
  for (let i = 0; i < height; i++) {
    fill(lerpColor(c1, c2, i / height));
    rect(0, i, width, 1);
  }
}

